 <el-table-column column-key="inventory" class-name="listing-metric-cell" align="center" :width="columnWidths.inventory||350"><template #header><el-tooltip content="可售＝可配送库存；接收中＝亚马逊接收中；待调仓＝亚马逊仓库之间调拨的库存；入库中＝仓内处理中（可能含测量、检查）；在途＝亚马逊已发货未接收口径，可能含已送达待接收。计划未发货不计在途。"><span class="metric-heading">FBA可售｜接收中｜待调仓｜入库中｜在途 <el-icon><InfoFilled/></el-icon></span></el-tooltip></template><template #default="{row}"><div class="metric-stack"><el-tooltip :content="stockTip(row)"><div class="metric-values">{{row.inventory.available??'—'}} <i>｜</i> {{row.inventory.receiving??'—'}} <i>｜</i> {{row.inventory.transfer??'—'}} <i>｜</i> {{row.inventory.processing??'—'}} <i>｜</i> {{row.inventory.shipped??'—'}}</div></el-tooltip><div class="metric-notes"><div v-if="row.inventory.error||row.inventory.stale" class="cell-sub">{{row.inventory.error?'读取异常，旧值保留':row.inventory.synced_at?'库存待刷新':'尚未同步'}}</div></div></div></template></el-table-column>
 <el-table-column column-key="arrivals" class-name="listing-metric-cell" align="center" :width="columnWidths.arrivals||205"><template #header><el-tooltip content="未来 15/30/60 天内累计预计到仓件数（含今天）；按当前站点计划的送达窗口结束日期统计。三个数字不能相加；* 表示有缺失或逾期数据。点击数字查看货件。"><span class="metric-heading">15天｜30天｜60天内到达 <el-icon><InfoFilled/></el-icon></span></el-tooltip></template><template #default="{row}"><div class="metric-stack"><button class="arrival-link metric-values" @click.stop="arrivalRow=row" :aria-label="`${row.sku} 预计到达明细`"><template v-for="(days,i) in ['15','30','60']" :key="days"><i v-if="i">｜</i>{{row.arrivals.values[days]??'—'}}</template><sup v-if="row.arrivals.partial">*</sup></button><div class="metric-notes"><div class="cell-sub arrival-note">{{['queued','running'].includes(row.arrivals.status)?'正在同步…':row.arrivals.error?'同步异常，请查看明细':row.arrivals.unknown+row.arrivals.unverified?`待核对 ${row.arrivals.unknown+row.arrivals.unverified} 件`:row.arrivals.overdue?`已逾期 ${row.arrivals.overdue} 件`:!row.arrivals.synced_at?'尚未同步':row.arrivals.stale?'到达数据待刷新':row.arrivals.later?`60天后 ${row.arrivals.later} 件`:'预计到仓 · 点击查看'}}</div></div></div></template></el-table-column>
